WITH metrics AS (SELECT *, DENSE_RANK() OVER (PARTITION BY account_type ORDER BY balance DESC) AS balance_dense_rank, CUME_DIST() OVER (PARTITION BY status ORDER BY balance DESC) AS balance_cume_dist FROM accounts) SELECT DATE_TRUNC('YEAR', opened_date) AS year_start, PERCENTILE_APPROX(balance_cume_dist, ARRAY(0.25, 0.5, 0.75)) AS balance_cume_dist_quartiles, COUNT(*) AS row_count FROM metrics GROUP BY DATE_TRUNC('YEAR', opened_date) ORDER BY year_start DESC
